alter table public.ingestion_sources drop constraint ingestion_sources_kind_check;
alter table public.ingestion_sources add constraint ingestion_sources_kind_check check(kind in ('jsonld','greenhouse','lever','ashby','smartrecruiters','workable','recruitee','remotive','arbeitnow','adzuna','jooble','reed','brac'));
alter table public.jobs drop constraint jobs_source_kind_check;
alter table public.jobs add constraint jobs_source_kind_check check(source_kind in ('paste','email_alert','jsonld','greenhouse','lever','curated','sample','ashby','smartrecruiters','workable','recruitee','remotive','arbeitnow','adzuna','jooble','reed','brac'));
insert into public.ingestion_sources(kind,name,board_token,country,company,active) values('brac','BRAC careers','brac','BD','BRAC',true) on conflict(kind,board_token) where board_token is not null do nothing;
-- Configure detail-page discovery only for verified public employer listings.
alter table public.ingestion_sources add column detail_path text check(detail_path is null or detail_path like '/%');
insert into public.ingestion_sources(kind,name,url,country,company,active,detail_path)
select 'jsonld','BRAC IT careers','https://www.bracits.com/career/','BD','BRAC IT',true,'/jobs/'
where not exists(select 1 from public.ingestion_sources where kind='jsonld' and url='https://www.bracits.com/career/');

-- Public GET evidence collected 2026-10-22: confirmed missing board endpoints, not expiry evidence for existing jobs.
create table public.ingestion_source_quarantine (
 source_id uuid primary key references public.ingestion_sources(id) on delete cascade,
 original jsonb not null, evidence jsonb not null, quarantined_at timestamptz not null default now()
);
alter table public.ingestion_source_quarantine enable row level security;
revoke all on public.ingestion_source_quarantine from anon,authenticated;
grant all on public.ingestion_source_quarantine to service_role;
