insert into public.ingestion_source_quarantine(source_id,original,evidence)
select s.id,to_jsonb(s),jsonb_build_object('http',404,'endpoint',e.endpoint,'checked_on','2026-10-22','reason','Board endpoint does not exist')
from public.ingestion_sources s join evidence e on e.id=s.id and e.kind=s.kind and e.token=s.board_token
where s.active;
update public.ingestion_sources s set active=false,last_status='quarantined',last_error='Verified HTTP 404: invalid board configuration; existing jobs preserved'
where exists(select 1 from public.ingestion_source_quarantine q where q.source_id=s.id);
